retiredStyles.css:
/* streich-bros-bundle.css — extracted 2026-09-06 from the inline \3c style> in employee-bundles/streich-bros-bundle.html (Rule 3). */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --streich-bros-bundle-blue: #2c2997;
    --streich-bros-bundle-yellow: #ffdd2d;
    --streich-bros-bundle-red: #dc3e32;
    --streich-bros-bundle-blue-2: #1f1d6b;
    --primary-color: var(--streich-bros-bundle-blue);
    --secondary-color: var(--streich-bros-bundle-yellow);
    --accent-color: var(--streich-bros-bundle-red);
    --dark-text: var(--gray-700);
    --light-text: var(--print-line);
}
/* stylelint-enable color-no-hex */

body {
    font-family: Roboto, sans-serif;
    background-color: var(--gray-100);
    color: var(--dark-text);
}

.header {
    background-color: var(--primary-color);
    color: white;
    padding: 2rem 0;
    margin-bottom: 2rem;
}

.logo-container {
    background: white;
    padding: 1rem;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    display: inline-block;
}

.logo-container img {
    max-width: 100%;
    height: auto;
    max-height: 120px;
}

.header h1 {
    font-family: 'Roboto Slab', serif;
    font-weight: 700;
    margin-bottom: 0.5rem;
    letter-spacing: 0.5px;
}

.header p {
    opacity: 0.95;
    margin-bottom: 0;
    font-weight: 300;
}

.content-section {
    background: white;
    border-radius: 8px;
    padding: 2rem;
    margin-bottom: 1.5rem;
    box-shadow: 0 2px 4px rgb(0 0 0 / 10%);
}

.section-title {
    color: var(--primary-color);
    font-weight: 600;
    font-family: 'Roboto Slab', serif;
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 2px solid var(--brand-100);
}

.important-note {
    background-color: var(--store-rush-soft);
    border-left: 4px solid var(--secondary-color);
    padding: 1rem 1.5rem;
    margin-bottom: 1.5rem;
    border-radius: 4px;
}

.important-note i {
    color: var(--secondary-color);
    margin-right: 0.5rem;
}

.instructions-box {
    background-color: var(--gray-50);
    border-left: 4px solid var(--primary-color);
    padding: 1.5rem;
    border-radius: 4px;
}

.instruction-step {
    display: flex;
    align-items: start;
    margin-bottom: 1rem;
}

.instruction-step:last-child {
    margin-bottom: 0;
}

.step-number {
    background-color: var(--primary-color);
    color: white;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
    margin-right: 1rem;
    flex-shrink: 0;
}

.step-content {
    flex: 1;
    padding-top: 4px;
    font-weight: 400;
}

.company-bundles {
    background: white;
    border-radius: 8px;
    padding: 2rem;
    margin-top: 2rem;
    box-shadow: 0 2px 4px rgb(0 0 0 / 10%);
}

.bundles-title {
    font-family: 'Roboto Slab', serif;
    font-weight: 600;
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    color: var(--dark-text);
    letter-spacing: 0.5px;
}

.bundles-title i {
    margin-right: 0.5rem;
    color: var(--primary-color);
}

.bundles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 1rem;
}

.bundle-card {
    border: 2px dashed var(--store-line);
    border-radius: 8px;
    padding: 1.5rem 1rem;
    text-align: center;
    cursor: pointer;
    transition: all 0.3s ease;
    background: white;
}

.bundle-card:hover {
    border-color: var(--primary-color);
    background-color: var(--color-ruth-tint);
    transform: translateY(-2px);
    box-shadow: 0 4px 8px rgb(44 41 151 / 15%);
}

.bundle-card.active {
    background-color: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
    border-style: solid;
    box-shadow: 0 4px 12px rgb(44 41 151 / 25%);
}

.bundle-card.active:hover {
    background-color: var(--streich-bros-bundle-blue-2);
}

.bundle-card i {
    font-size: 2rem;
    margin-bottom: 0.5rem;
    opacity: 0.7;
}

.bundle-card.active i {
    opacity: 1;
}

.bundle-name {
    font-weight: 600;
    margin-bottom: 0.25rem;
    letter-spacing: 0.3px;
}

.bundle-status {
    font-size: 0.85rem;
    opacity: 0.7;
}

.instructions-box h5 {
    color: var(--primary-color);
    font-family: 'Roboto Slab', serif;
    font-weight: 600;
    letter-spacing: 0.3px;
}

.caspio-container {
    margin-top: 1.5rem;
    min-height: 400px;
}

.footer-logo {
    text-align: center;
    padding: 2rem 0;
}

.footer-logo img {
    max-width: 300px;
    height: auto;
    opacity: 0.7;
    transition: opacity 0.3s ease;
}

.footer-logo img:hover {
    opacity: 0.9;
}

@media (width <= 768px) {
    .bundles-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .header h1 {
        font-size: 1.75rem;
    }
}

/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }

